def get_bge_embedding(text_str: str) -> list[float]:
    payload = json.dumps({
        "model": "bge-m3:latest",
        "prompt": text_str[:4000]
    }).encode("utf-8")
    req = urllib.request.Request(
        OLLAMA_EMBED_URL,
        data=payload,
        headers={"Content-Type": "application/json"}
    )
    with urllib.request.urlopen(req, timeout=90) as resp:
        return json.loads(resp.read().decode("utf-8"))["embedding"]

DOSSIERS = [{'category': 'texts', 'slug': 'text-sirupanarruppadai-saltpan-and-umanar-poetry', 'file': 'text-sirupanarruppadai-saltpan-and-umanar-poetry.md', 'name_en': 'Sirupanarruppadai Saltpan Ecology & Umanar Caravan Hymns', 'name_ta': 'சிறுபாணாற்றுப்படை உப்பள இயற்கை மற்றும் உமணர் வணிகப் பெருவழிப் பாடல்கள்', 'era': 'Sangam Classical Era (c. 200 BCE – 200 CE)', 'thinai': 'Neithal / Mullai', 'summary_en': 'Classical Sangam verses in Sirupanarruppadai (lines 115-130) and Akananuru documenting coastal solar saltpans (Alam), Umanar merchant bullock carts, salt-for-paddy barter (Uppe-nel-maari), and migratory family convoys.', 'summary_ta': 'சிறுபாணாற்றுப்படை மற்றும் அகநானூற்றுப் பாடல்களில் விவரிக்கப்படும் நெய்தல் உப்பளங்கள், மாட்டு வண்டிகளில் உப்பு ஏற்றிச் சென்ற உமணர் வணிகக் கூட்டங்கள், உப்புக்கு நெல் மாற்றும் பண்டமாற்று முறை மற்றும் பயணக் குடியிருப்புகள்.', 'sources': ['Sirupanarruppadai lines 115-130', 'Akananuru 140, 390', 'Narrinai 183', 'Purananuru 386'], 'content': '---\ntitle: "Sirupanarruppadai Saltpan Ecology & Umanar Caravan Hymns"\nslug: "text-sirupanarruppadai-saltpan-and-umanar-poetry"\ncategory: "texts"\ntype: "text"\nera: "Sangam Classical Era (c. 200 BCE – 200 CE)"\nthinai: "Neithal / Mullai"\nlanguage: "ta / en"\nsources:\n  - "Sirupanarruppadai lines 115-130"\n  - "Akananuru 140, 390"\n  - "Narrinai 183"\n  - "Purananuru 386"\n---\n\n# Sirupanarruppadai Saltpan Ecology & Umanar Caravan Hymns\n\n## 1. Neithal Coastline Saltpan Landscape (Alam)\nClassical Tamil literature offers vivid poetic records of the extensive solar evaporation beds (*Alam*) lining the Coromandel and Gulf of Mannar shores. In *Sirupanarruppadai* (lines 115–125), the poet Nallur Nathathanar depicts the glittering white crystal fields of coastal saltpans:\n> *"Vellai uppin kollai kaala..."* — "The wide fields of gleaming white salt, harvested under scorching maritime suns, where sea brines dry into crystalline snow."\n\nIn *Akananuru* (v. 140), young Umanar women (*Umathiyar*) are portrayed selling crystal salt from door to door in agricultural towns, chanting their barter calls.\n\n## 2. Umanar Caravan Logistics & Bullock Cart Trains\nThe inland distribution of sea salt was the lifeblood of inland agrarian life. Hereditary salt merchants known as *Umanar* organized massive trans-regional caravans:\n- **Covered Bullock Carts (Saakadu)**: Sturdy wooden carts fitted with arched woven bamboo canopies (*panthal*) to protect delicate hygroscopic salt crystals from sudden rain showers.\n- **Family Convoys**: Umanar traveled in multi-generational clans with wives, nursing children, watchdogs, and armed bowmen protecting the convoy from highway bandits (*Maravar*).\n- **Overnight Bivouacs (Padugai)**: Caravans encircled their carts in defensive defensive wagon-rings (*Vandi-valayam*) along riverbanks and shady banyan groves.\n\n## 3. The Equal Value Barter System (Uppe-Nel-Maari)\nBefore monetized markets dominated interior trade, salt and unhusked paddy (*nel*) shared a direct, legally sanctioned parity:\n- One measure of coarse white sea salt was exchanged for exactly one equal measure of mountain grain (*Nellum uppum ner-ere*).\n- This direct barter enabled high-altitude hill dwellers (*Kurinji*) and pastoral herders (*Mullai*) to acquire essential dietary minerals in exchange for forest tubers, millets, and wild honey.\n', 'node_type': 'text', 'year_start': -300, 'year_end': 300}, {'category': 'inscriptions', 'slug': 'insc-marakkanam-saltpan-royal-charters', 'file': 'insc-marakkanam-saltpan-royal-charters.md', 'name_en': 'Marakkanam Eyilpattinam Royal Saltpan Concessions & Transit Toll Charters', 'name_ta': 'மரகானம் எயில்பட்டினம் அரச உப்பள மானியங்கள் மற்றும் சுங்க வரிப் பட்டயங்கள்', 'era': 'Pallava to Imperial Chola Era (c. 800–1050 CE)', 'thinai': 'Neithal', 'summary_en': 'Epigraphs from the Bhumisvara temple at Marakkanam recording royal saltpan boundaries, temple salt tithes, canal brine sluice rights, and caravan road tolls under Rajaraja I and Rajendra I.', 'summary_ta': 'மரகானம் பூமீஸ்வரர் கோயில் கல்வெட்டுகளில் காணப்படும் அரச உப்பள எல்லைகள், கோயில் உப்பு மானியங்கள், கடல்நீர் கால்வாய் மதகு உரிமைகள் மற்றும் உமணர் வண்டிச் சுங்க வரிகள்.', 'sources': ['South Indian Inscriptions Vol. XIX, No. 214', 'Annual Report on South Indian Epigraphy 1919, No. 31', 'Marakkanam Temple Epigraphs'], 'content': '---\ntitle: "Marakkanam Eyilpattinam Royal Saltpan Concessions & Transit Toll Charters"\nslug: "insc-marakkanam-saltpan-royal-charters"\ncategory: "inscriptions"\ntype: "inscription"\nera: "Pallava to Imperial Chola Era (c. 800–1050 CE)"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "South Indian Inscriptions Vol. XIX, No. 214"\n  - "Annual Report on South Indian Epigraphy 1919, No. 31"\n  - "Marakkanam Temple Epigraphs"\n---\n\n# Marakkanam Eyilpattinam Royal Saltpan Concessions & Transit Toll Charters\n\n## 1. Maritime Saltpan Endowments at Marakkanam\nThe coastal town of Marakkanam (the classical *Eyilpattinam* of Sangam texts and *Sopatma* of the Greco-Roman Periplus) was the premier salt-manufacturing capital of northern Tamil Nadu. Epigraphs of the Pallava and Chola dynasties inscribed upon the walls of the local Bhumisvara temple document extensive royal concessions granted to salt-making corporations:\n- **Uppala-Kani**: Demarcated rectangular salt fields granted in perpetuity to religious endowments and temple kitchens.\n- **Uppu-Kuru**: Mandatory royal levies of three *marakkals* of salt per cartload dedicated to temple oil-lamps and food offerings.\n\n## 2. Inscriptional Regulation of Brine Sluices\nThe charters strictly codify the maintenance of tidal intake sluices (*ali-vaay*):\n- Saltmakers were legally entitled to breach barrier sandbars during high spring tides to flood coastal mudflats with concentrated seawater.\n- Royal overseers (*Uppu-Aayam-Kavalar*) inspected crystallization pans to ensure fine white grade crystal production free from clay sediment.\n', 'node_type': 'inscription', 'year_start': 985, 'year_end': 1280}, {'category': 'inscriptions', 'slug': 'insc-kayalpattinam-salt-revenue-and-measure-charters', 'file': 'insc-kayalpattinam-salt-revenue-and-measure-charters.md', 'name_en': 'Kayalpattinam & Tambraparni Delta Salt Revenue, Measures & Guild Toll Charters', 'name_ta': 'காயல்பட்டினம் மற்றும் தாமிரபரணி கழிமுக உப்பு வரி, அளவை மற்றும் வணிகக் குழுப் பட்டயங்கள்', 'era': 'Medieval Pandya Era (c. 1250–1350 CE)', 'thinai': 'Neithal', 'summary_en': 'Stone inscriptions and temple charters from the lower Tambraparni delta and Gulf of Mannar delineating Pandya salt revenue assessments, standard brass dry measures, and merchant guild export duties.', 'summary_ta': 'கீழத் தாமிரபரணி கழிமுகம் மற்றும் மன்னார் வளைகுடா கல்வெட்டுகளில் பதிவான பாண்டியர் கால உப்பு வரி மதிப்பீடுகள், நிலையான செப்பு மரக்கால் அளவைகள் மற்றும் வணிகக் குழு ஏற்றுமதி வரிகள்.', 'sources': ['South Indian Inscriptions Vol. XIV, No. 122', 'Tiruchendur Temple Stone Inscriptions', 'Travancore Archaeological Series Vol. I'], 'content': '---\ntitle: "Kayalpattinam & Tambraparni Delta Salt Revenue, Measures & Guild Toll Charters"\nslug: "insc-kayalpattinam-salt-revenue-and-measure-charters"\ncategory: "inscriptions"\ntype: "inscription"\nera: "Medieval Pandya Era (c. 1250–1350 CE)"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "South Indian Inscriptions Vol. XIV, No. 122"\n  - "Tiruchendur Temple Stone Inscriptions"\n  - "Travancore Archaeological Series Vol. I"\n---\n\n# Kayalpattinam & Tambraparni Delta Salt Revenue, Measures & Guild Toll Charters\n\n## 1. Southern Salt Trade & Pandya Royal Revenue\nIn the protected tidal estuaries of the Gulf of Mannar near Kayalpattinam and Korkai, solar salt extraction formed a key pillar of Pandyan state finance. Inscriptions at Tiruchendur and Korkai catalog:\n- **Uppu-Irai**: The crown tax assessed per *padu* (crystallization bed).\n- **Aynoorruvar & Manigramam Guild Concessions**: Trans-oceanic merchant guilds received royal dispensations to load overseas dhows with salted dried fish and refined salt for trade with Ceylon, the Maldives, and Sumatra.\n\n## 2. Standardized Volumetric Salt Measures\nThe charters explicitly prohibit merchant fraud by enforcing officially stamped royal measures:\n- **Rajarajan-Marakkal**: Calibrated brass cylinders bearing the Pandyan twin-fish crest (*Kayal-muthirai*).\n- **Toll Checkpoints (Chavadi)**: Caravan roads passing from the coast to the interior Tirunelveli plains were staffed with customs officers who levied tolls based on the count of bullock packs (*pothivandi*).\n', 'node_type': 'inscription', 'year_start': 1250, 'year_end': 1350}, {'category': 'concepts', 'slug': 'concept-solar-evaporation-pans-and-brine-fractionation', 'file': 'concept-solar-evaporation-pans-and-brine-fractionation.md', 'name_en': 'Solar Evaporation Saltpans, Hydraulic Brine Gradient & Crystal Fractionation', 'name_ta': 'சூரிய வெப்ப உப்பளங்கள், கடல்நீர் அடர்த்திப் படுகை மற்றும் படிகப் பிரிப்பு நுட்பம்', 'era': 'Sangam to Medieval Era', 'thinai': 'Neithal', 'summary_en': 'Hydraulic engineering of traditional Tamil solar salt complexes: tidal intake reservoirs, condensing evaporation lagoons (Alangam), and compacted clay crystallization beds yielding pure sodium chloride.', 'summary_ta': 'பாரம்பரியத் தமிழ் உப்பளங்களின் நீர்மப் பொறியியல்: கடல்நீர் தேக்கும் ஆழ்குளங்கள், சூரிய ஆவியாதல் நடுத்தரப் படுகைகள் மற்றும் களிமண் தரை படிகப் படுக்கைகளில் தூய உப்பு பிரித்தெடுக்கும் முறை.', 'sources': ['Sirupanarruppadai lines 118-124', 'Akananuru 390', 'Traditional Coastal Saltmaking Ethnography'], 'content': '---\ntitle: "Solar Evaporation Saltpans, Hydraulic Brine Gradient & Crystal Fractionation"\nslug: "concept-solar-evaporation-pans-and-brine-fractionation"\ncategory: "concepts"\ntype: "concept"\nera: "Sangam to Medieval Era"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "Sirupanarruppadai lines 118-124"\n  - "Akananuru 390"\n  - "Traditional Coastal Saltmaking Ethnography"\n---\n\n# Solar Evaporation Saltpans, Hydraulic Brine Gradient & Crystal Fractionation\n\n## 1. Multi-Stage Hydraulic Basin Architecture\nTraditional Tamil salt engineers (*Alam-kallar*) did not evaporate raw seawater directly in one basin, which would precipitate bitter magnesium salts. Instead, they designed a graduated multi-tier gravity-fed evaporation system:\n1. **Intake Estuary Reservoir (Perum-Kulam)**: Seawater (approx. 3.5% salinity) was captured during high tide via counterweighted sluice gates and retained to settle suspended organic silt and sand.\n2. **Evaporation Condensers (Marapu / Alangam)**: Shallow intermediate pans where solar radiation and maritime breeze evaporated water until salinity rose to 15–20° Baumé. Calcium carbonate and iron oxides precipitated out first.\n3. **Crystallization Beds (Patti / Alam)**: Highly compacted, flat clay basins lined with tamped black river silt where saturated brine (25–28° Baumé) deposited pure white cubic sodium chloride (*NaCl*) crystals.\n\n## 2. Bed Compaction & Crystal Scraping\n- Crystallization beds were rolled repeatedly with heavy stone cylinders and tamped with flat wooden mallets (*thattuppalagai*) to create an impermeable ceramic-like mud floor.\n- Harvesters used wide wooden rakes (*vari-palagai*) with bevelled edges to gently skim crystal crusts from the surface without digging into the underlying clay, preventing gray mud discoloration.\n', 'node_type': 'concept', 'year_start': -300, 'year_end': 300}, {'category': 'concepts', 'slug': 'concept-umanar-bullock-cart-caravans-and-salt-barter-economics', 'file': 'concept-umanar-bullock-cart-caravans-and-salt-barter-economics.md', 'name_en': 'Umanar Merchant Caravans, Pack-Bullock Logistics & Trans-Thinai Barter Economics', 'name_ta': 'உமணர் வணிகக் குழுக்கள், பொதிமாட்டுப் போக்குவரத்து மற்றும் திணை கடந்த பண்டமாற்றுப் பொருளாதாரம்', 'era': 'Sangam Classical Era', 'thinai': 'Neithal to Kurinji', 'summary_en': 'Socio-economic mechanics of ancient Tamil salt trade: nomadic cart trains, long-distance pack-bullock trails crossing the Western Ghats, and the foundational barter ratios connecting coastal and highland thinais.', 'summary_ta': 'பழங்காலத் தமிழ் உப்பு வணிகத்தின் சமூக-பொருளாதார நுட்பங்கள்: நாடோடி வண்டித் தொடர்கள், மேற்குத் தொடர்ச்சி மலைகளைக் கடக்கும் பொதிமாட்டுப் பாதைகள் மற்றும் நெய்தல்-குறிஞ்சி நிலங்களை இணைத்த பண்டமாற்று விகிதங்கள்.', 'sources': ['Akananuru 140, 191, 390', 'Perumpanarruppadai 60-75', 'Tolkappiyam Porulatikaram 22'], 'content': '---\ntitle: "Umanar Merchant Caravans, Pack-Bullock Logistics & Trans-Thinai Barter Economics"\nslug: "concept-umanar-bullock-cart-caravans-and-salt-barter-economics"\ncategory: "concepts"\ntype: "concept"\nera: "Sangam Classical Era"\nthinai: "Neithal to Kurinji"\nlanguage: "ta / en"\nsources:\n  - "Akananuru 140, 191, 390"\n  - "Perumpanarruppadai 60-75"\n  - "Tolkappiyam Porulatikaram 22"\n---\n\n# Umanar Merchant Caravans, Pack-Bullock Logistics & Trans-Thinai Barter Economics\n\n## 1. Caravan Composition & March Discipline\nThe *Umanar* formed one of the earliest organized merchant communities in South Asia. Their expeditions spanned several months across difficult terrain:\n- **Convoy Architecture**: Up to 300 covered two-wheeled wooden carts hauled by trained twin Kangeyam bullocks. Pack bullocks (*pothi-maadu*) laden with twin woven coir bags navigated rocky mountain footpaths impassable to carts.\n- **Scouts & Outriders**: Armed scouts mounted on swift ponies rode half a league ahead to reconnoiter river crossings, waterholes, and hostile tribal raiding parties.\n- **Acoustic Warning**: Carts were fitted with hollow wooden clappers and bronze neck bells whose rhythmic chimes echoed across scrub forests, warning travelers and wild beasts of the caravan\'s approach.\n\n## 2. Trans-Thinai Economic Integration\nSalt was the indispensable catalyst that integrated the five classical ecological zones (*Ainthinai*):\n- *Neithal* produced the salt.\n- *Marutham* traded harvested wetland paddy and forged iron tools in return.\n- *Mullai* bartered clarified butter (*ghee*) and pastoral milk products.\n- *Kurinji* and *Palai* supplied pepper, dried hill ginger, fragrant sandalwood, and ivory in exchange for the preservative mineral.\n', 'node_type': 'concept', 'year_start': -300, 'year_end': 300}, {'category': 'concepts', 'slug': 'concept-clay-lined-salt-storage-silos-and-moisture-protection', 'file': 'concept-clay-lined-salt-storage-silos-and-moisture-protection.md', 'name_en': 'Elevated Clay-Lined Salt Storage Silos, Thatched Pyramids & Moisture Dissipation', 'name_ta': 'மேடை உப்புக் களஞ்சியங்கள், கூம்பு வடிவ வைக்கோல் கூரைகள் மற்றும் ஈரப்பதம் தடுப்புப் பொறியியல்', 'era': 'Sangam to Chola Era', 'thinai': 'Neithal / Marutham', 'summary_en': 'Indigenous storage engineering for preserving thousands of kalams of crystalline salt through monsoonal humidity: raised earthen platforms, lime plaster linings, and sloped palmyra thatched pyramids.', 'summary_ta': 'பருவமழைக் கால ஈரப்பதத்திலிருந்து பல்லாயிரக்கணக்கான கலம் உப்பைப் பாதுகாக்கும் தரைமேடை உப்புக் களஞ்சியங்கள், சுண்ணாம்பு சாந்து பூச்சு மற்றும் கூம்பு வடிவப் பனையோலை கூரை வடிவமைப்பு.', 'sources': ['Narrinai 183', 'South Indian Inscriptions Vol. XIX', 'Tamil Architectural Ethnography'], 'content': '---\ntitle: "Elevated Clay-Lined Salt Storage Silos, Thatched Pyramids & Moisture Dissipation"\nslug: "concept-clay-lined-salt-storage-silos-and-moisture-protection"\ncategory: "concepts"\ntype: "concept"\nera: "Sangam to Chola Era"\nthinai: "Neithal / Marutham"\nlanguage: "ta / en"\nsources:\n  - "Narrinai 183"\n  - "South Indian Inscriptions Vol. XIX"\n  - "Tamil Architectural Ethnography"\n---\n\n# Elevated Clay-Lined Salt Storage Silos, Thatched Pyramids & Moisture Dissipation\n\n## 1. The Threat of Monsoonal Deliquescence\nBecause sodium chloride is hygroscopic and trace magnesium chloride impurities rapidly absorb ambient atmospheric moisture, storing salt in humid coastal Tamil climates required specialized architectural insulation:\n- In unsealed storage, monsoonal rains would dissolve entire heaps into brine run-off.\n- Ancient builders developed specialized storehouses known as *Uppu-Kottai* or *Uppu-Pathayam*.\n\n## 2. Structural Engineering of Salt Pyramids\n1. **Elevated Sand Platforms (Kottai-Medu)**: Salt was heaped upon circular rammed-earth platforms elevated 3 to 4 feet above ground level to prevent groundwater capillary action.\n2. **Straw & Lime Barrier**: The bottom of the mound was covered with dry paddy straw and fired potsherds to allow moisture to drain downward away from the bulk crystals.\n3. **Thatched Palmyra Cone**: The conical mound was thatched with multi-layered palmyra fronds (*panai-olai*) and sealed around the apex with a cap of water-repellent clay, shedding torrential northeast monsoon rains while allowing internal aeration.\n', 'node_type': 'concept', 'year_start': -300, 'year_end': 300}, {'category': 'concepts', 'slug': 'concept-salt-measuring-metrology-and-coastal-customs-tolls', 'file': 'concept-salt-measuring-metrology-and-coastal-customs-tolls.md', 'name_en': 'Ancient Tamil Salt Metrology, Volumetric Marakkal Measures & Coastal Toll Levies', 'name_ta': 'பழங்காலத் தமிழ் உப்பு அளவியல், மரக்கால் அளவைகள் மற்றும் கடற்கரை சுங்க வரிகள்', 'era': 'Sangam to Medieval Chola/Pandya Era', 'thinai': 'Neithal', 'summary_en': 'Standardized dry volumetric measurement of salt using sevidu, aazhakku, uri, nazi, and marakkal units; royal customs checkpoint inspections (Ulgu); and transit tithes (Uppu-ayam).', 'summary_ta': 'செவிடு, ஆழாக்கு, உறி, நாழி, குறுணி மற்றும் மரக்கால் கொண்ட நிலையான உலரளவு அளவியல்; உப்பளச் சுங்கச் சாவடி சோதனைகள் (உல்கு) மற்றும் அரச உப்பு வரிகள்.', 'sources': ['Pattinappalai lines 125-135', 'Tolkappiyam Eluttatikaram 164', 'South Indian Inscriptions Vol. II'], 'content': '---\ntitle: "Ancient Tamil Salt Metrology, Volumetric Marakkal Measures & Coastal Toll Levies"\nslug: "concept-salt-measuring-metrology-and-coastal-customs-tolls"\ncategory: "concepts"\ntype: "concept"\nera: "Sangam to Medieval Chola/Pandya Era"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "Pattinappalai lines 125-135"\n  - "Tolkappiyam Eluttatikaram 164"\n  - "South Indian Inscriptions Vol. II"\n---\n\n# Ancient Tamil Salt Metrology, Volumetric Marakkal Measures & Coastal Toll Levies\n\n## 1. Standardized Volumetric Graduations\nTamil metrology utilized an integrated dry volume scale applied uniformly to both grains and salt:\n- 5 Sevidu = 1 Aazhakku\n- 2 Aazhakku = 1 Uzhavakku\n- 2 Uzhavakku = 1 Uri\n- 2 Uri = 1 Naazhi (Padi)\n- 8 Naazhi = 1 Marakkal (Kuruni)\n- 12 Marakkal = 1 Kalam\n\nBecause coarse crystal salt contains variable air voids, royal market inspectors enforced standardized leveling bars (*Thada-kampu*) swept across the brim of the brass *marakkal* to eliminate "heaped" overcharging.\n\n## 2. The Ulgu Customs System\nIn *Pattinappalai*, the customs checkpoint (*Ulgu-sey-kottam*) at port entrances is described where royal officers stamped goods with the tiger signet (*Puli-pori*). Salt carts exiting the coast into interior trade roads were assessed:\n- **Vandi-Irai**: Toll per laden two-bullock cart.\n- **Pothi-Kattanam**: Small transit levy per pack-animal paid in physical salt measures to feed roadside toll guards and road-clearing laborers.\n', 'node_type': 'concept', 'year_start': 985, 'year_end': 1280}, {'category': 'characters', 'slug': 'char-marakkanam-saltpan-master-alam-kavalar', 'file': 'char-marakkanam-saltpan-master-alam-kavalar.md', 'name_en': 'Chief Saltpan Master & Brine Hydrologist of Marakkanam (Alam-Kavalar)', 'name_ta': 'மரகானம் தலைமை உப்பள மேற்பார்வையாளர் மற்றும் நீர்மவியல் வல்லுநர் (அளக் காவலர்)', 'era': 'Imperial Chola Era (c. 1000 CE)', 'thinai': 'Neithal', 'summary_en': 'Hereditary overseer of the Marakkanam imperial saltpans, master of tidal sluice gates, brine density grading, and royal crystal purity certifications.', 'summary_ta': 'மரகானத்தின் பேரரசு உப்பளங்களை நிர்வகித்த தலைமைப் பொறுப்பாளர்; ஓதக் கதவுகள், கடல்நீர் அடர்த்தி தரம் மற்றும் உப்பின் தூய்மைச் சான்றளிப்பில் தேர்ந்த அறிஞர்.', 'sources': ['Bhumisvara Temple Inscriptions', 'South Indian Inscriptions Vol. XIX'], 'content': '---\ntitle: "Chief Saltpan Master & Brine Hydrologist of Marakkanam (Alam-Kavalar)"\nslug: "char-marakkanam-saltpan-master-alam-kavalar"\ncategory: "characters"\ntype: "character"\nera: "Imperial Chola Era (c. 1000 CE)"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "Bhumisvara Temple Inscriptions"\n  - "South Indian Inscriptions Vol. XIX"\n---\n\n# Chief Saltpan Master & Brine Hydrologist of Marakkanam (Alam-Kavalar)\n\n## 1. Lineage & Administrative Authority\nHolding royal appointment from the Chola revenue board (*Puravu-vari-tinaikkalam*), the *Alam-Kavalar* directed operations across hundreds of acres of low-lying estuary lagoons at Marakkanam. He managed guilds of salt-rakers (*Uppu-kothar*) and supervised the flow of tidal sea waters through stone canals.\n\n## 2. Brine Hydrology & Density Testing\nWithout modern glass hydrometers, he gauged brine readiness using empirical fluid-density markers:\n- He floated a freshly laid sea-bird egg in the evaporating brine; if the egg floated with its top ridge breaking the surface, the density was judged perfect for transfer into crystallization beds.\n- He sampled crystal flakes on the tongue to detect trace bitterness from magnesium sulfate, ordering premature draining if off-flavors emerged.\n', 'node_type': 'character', 'year_start': -300, 'year_end': 1000}, {'category': 'characters', 'slug': 'char-umanar-caravan-chief-karum-ser-thalaivan', 'file': 'char-umanar-caravan-chief-karum-ser-thalaivan.md', 'name_en': 'Master Umanar Caravan Conductor & Convoy Commander (Karum-Ser-Thalaivan)', 'name_ta': 'உமணர் பெருவணிகத் தொடர் தலைமைத் தளபதி (கரும்சேர் தலைவன்)', 'era': 'Sangam Classical Era', 'thinai': 'Neithal to Kurinji', 'summary_en': 'Veteran navigator of trans-peninsular trade routes commanding hundreds of salt-laden bullock carts across arid tracts, river fords, and mountain bandit ambuscades.', 'summary_ta': 'நூற்றுக்கணக்கான மாட்டு வண்டிகள் கொண்ட உப்பு வணிகப் பெருந்தொடரை வழிநடத்திய மூத்த வணிக நாயகன்; பாலைவனப் பாதைகள், ஆற்றுத் துறைகள் மற்றும் வழிப்பறி திருடர்களை வென்ற பெருவீரன்.', 'sources': ['Akananuru 140, 390', 'Sirupanarruppadai lines 120-130'], 'content': '---\ntitle: "Master Umanar Caravan Conductor & Convoy Commander (Karum-Ser-Thalaivan)"\nslug: "char-umanar-caravan-chief-karum-ser-thalaivan"\ncategory: "characters"\ntype: "character"\nera: "Sangam Classical Era"\nthinai: "Neithal to Kurinji"\nlanguage: "ta / en"\nsources:\n  - "Akananuru 140, 390"\n  - "Sirupanarruppadai lines 120-130"\n---\n\n# Master Umanar Caravan Conductor & Convoy Commander (Karum-Ser-Thalaivan)\n\n## 1. Wilderness Navigation & Road Craft\nThe *Karum-Ser-Thalaivan* was the elected commander of the seasonal salt convoy. He possessed encyclopedic knowledge of:\n- **River Fords (Kadavukal)**: Calculating seasonal water depths along the Pennar, Palar, and Kaveri rivers so heavily weighted carts did not sink in shifting quicksands.\n- **Forage & Pasture Grounds**: Identifying safe overnight grasslands where draught bullocks could feed and recover without encroaching on royal paddy fields.\n\n## 2. Tactical Defense Against Highwaymen\nArmed with an iron-tipped spear and a recurve short-bow, he led the convoy\'s defense against *Eyinar* and *Maravar* ambushes in dry desert scrublands (*Palai*). At dusk, he supervised the interlocking of cart wheels into a fortified circular bastion (*Sakkara-kottam*), posting sentries around blazing neem-wood watch fires.\n', 'node_type': 'character', 'year_start': -300, 'year_end': 300}, {'category': 'places', 'slug': 'place-thoothukudi-ancient-solar-saltpans', 'file': 'place-thoothukudi-ancient-solar-saltpans.md', 'name_en': 'Thoothukudi Ancient Solar Saltpans & Gulf of Mannar Brine Haven', 'name_ta': 'தூத்துக்குடி பழங்காலச் சூரிய உப்பளங்கள் மற்றும் மன்னார் வளைகுடா உப்பு மையம்', 'era': 'Sangam to Pandya Era', 'thinai': 'Neithal', 'summary_en': 'Historic hyper-saline coastal basin in southern Tamil Nadu famous for low monsoonal rainfall, high dry winds, and continuous millennium-long production of high-purity solar salt.', 'summary_ta': 'தென் தமிழ்நாட்டின் மன்னார் வளைகுடாவில் அமைந்த வரலாற்றுச் சிறப்புமிக்க உப்பளத் தளம்; குறைந்த மழைப்பொழிவு, வறண்ட கடற்கரைக் காற்று மற்றும் ஆயிரம் ஆண்டுகளுக்கும் மேலாகத் தொடரும் உயர்தர உப்பு உற்பத்தி மையம்.', 'sources': ['Maduraikkanchi', 'Archaeological Survey of India Reports', 'South Indian Inscriptions Vol. XIV'], 'content': '---\ntitle: "Thoothukudi Ancient Solar Saltpans & Gulf of Mannar Brine Haven"\nslug: "place-thoothukudi-ancient-solar-saltpans"\ncategory: "places"\ntype: "place"\nera: "Sangam to Pandya Era"\nthinai: "Neithal"\nlanguage: "ta / en"\ncoordinates: [8.7642, 78.1348]\nsources:\n  - "Maduraikkanchi"\n  - "Archaeological Survey of India Reports"\n  - "South Indian Inscriptions Vol. XIV"\n---\n\n# Thoothukudi Ancient Solar Saltpans & Gulf of Mannar Brine Haven\n\n## 1. Climatological Ideal for Solar Crystallization\nThoothukudi (Tuticorin), located in the rain-shadow of the southern Western Ghats along the Gulf of Mannar, receives minimal rainfall during the southwest monsoon, experiencing sustained hot dry winds (*Kachaan-kaatru*) from May to September. This unique micro-climate allows rapid brine evaporation rates exceeding 8 mm per day, making it South India\'s greatest natural salt haven.\n\n## 2. Archaeological Remains & Maritime Trade\nArchaeological excavations along the old Tambraparni distributaries revealed stratified clay embankments, wooden salt shovels, and early historic potsherds incised with fish symbols. Large cargo catamarans (*thonigal*) anchored offshore to load bulk salt consignments destined for Sri Lanka and Indian Ocean littoral ports.\n', 'node_type': 'place', 'year_start': -300, 'year_end': 300}, {'category': 'texts', 'slug': 'text-mamallapuram-pallava-sculpture-and-vastu-hymns', 'file': 'text-mamallapuram-pallava-sculpture-and-vastu-hymns.md', 'name_en': 'Mamallapuram Pallava Sculptural Architecture & Vastu Agamic Hymns', 'name_ta': 'மாமல்லபுரம் பல்லவர் சிற்பக் கலை மற்றும் வாஸ்து ஆகமப் பாடல்கள்', 'era': 'Pallava Classical Era (c. 650–750 CE)', 'thinai': 'Neithal', 'summary_en': 'Literary and sculptural hymns from Tirumangai Alvar’s Nalayira Divya Prabandham, Dandin’s Avantisundari Katha, and Pallava eulogies celebrating the monolithic granitic temples, rock-cut caverns, and open-air bas-relief friezes of Mamallapuram.', 'summary_ta': 'திருமங்கையாழ்வாரின் நாலாயிர திவ்வியப் பிரபந்தப் பாடல்கள், தண்டியின் அவந்திசுந்தரி கதா மற்றும் பல்லவப் புகழுரைகளில் போற்றப்படும் மாமல்லபுரக் கற்றளிகள், ஒற்றைக்கல் இரதங்கள் மற்றும் திறந்தவெளிச் சிற்பத் தொகுதிகள்.', 'sources': ['Periya Tirumoli II.6 (Kadalmallai Tala-sayana hymns)', 'Avantisundari Katha of Dandin', 'Pallava Grantha Inscriptional Verses'], 'content': '---\ntitle: "Mamallapuram Pallava Sculptural Architecture & Vastu Agamic Hymns"\nslug: "text-mamallapuram-pallava-sculpture-and-vastu-hymns"\ncategory: "texts"\ntype: "text"\nera: "Pallava Classical Era (c. 650–750 CE)"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "Periya Tirumoli II.6 (Kadalmallai Tala-sayana hymns)"\n  - "Avantisundari Katha of Dandin"\n  - "Pallava Grantha Inscriptional Verses"\n---\n\n# Mamallapuram Pallava Sculptural Architecture & Vastu Agamic Hymns\n\n## 1. Classical Literature on Kadalmallai (Mamallapuram)\nIn the 8th century CE, the Vaishnava saint Tirumangai Alvar visited the seaport of Mamallapuram (known classically as *Kadalmallai* or *Mallai-munthurai*) and recorded the maritime vitality and sculptural majesty of its shrines:\n> *"Kadal-soozh mallai kidaitharule... kal-eduthu cheytha kovil..."* — "At sea-girt Mallai, where great sailing vessels laden with mountain treasures and elephant tusks ride the ocean swells, the Lord reposes in temples carved directly from primordial stone."\n\nThe court poet Dandin (c. 700 CE) in *Avantisundari Katha* describes master sculptors (*sthapatis*) at Mamallapuram repairing a colossal stone image of Vishnu on the shore, marveling that their joinery was so precise it appeared as if formed from a single living crystal.\n\n## 2. Transition from Perishable Timber to Imperishable Granite\nThe Mandagapattu inscription of Mahendravarman I (c. 615 CE) declares the philosophical revolution that gave birth to Mamallapuram’s rock art:\n- The king constructed a sanctuary for Brahma, Isvara, and Vishnu without brick (*isthaka*), without timber (*druma*), without metal (*loha*), and without mortar (*sudha*).\n- This marked the deliberate shift from perishable vernacular timber construction to sculpting eternal monuments directly out of South India’s crystalline charnockite granite bedrock.\n', 'node_type': 'text', 'year_start': 600, 'year_end': 800}, {'category': 'inscriptions', 'slug': 'insc-mamallapuram-dharmaraja-ratha-biruda-epigraphs', 'file': 'insc-mamallapuram-dharmaraja-ratha-biruda-epigraphs.md', 'name_en': 'Mamallapuram Dharmaraja Ratha Royal Birudas & Master Sculptor Epigraphs', 'name_ta': 'மாமல்லபுரம் தர்மராஜ இரதம் அரச விருதுகள் மற்றும் தலைமைச் சிற்பி கல்வெட்டுகள்', 'era': 'Pallava Classical Era (c. 640–690 CE)', 'thinai': 'Neithal', 'summary_en': 'Archaic Pallava Grantha inscriptions incised upon the stories of the Dharmaraja Ratha recording over twenty royal titles (Birudas) of Narasimhavarman I Mamalla and royal master sculptors (Kevadha).', 'summary_ta': 'தர்மராஜ இரதத்தின் தளங்களில் பொறிக்கப்பட்ட தொன்மையான பல்லவ கிரந்தக் கல்வெட்டுகள்; நரசிம்மவர்ம மாமல்லனின் இருபதுக்கும் மேற்பட்ட பட்டப் பெயர்கள் மற்றும் அரச தலைமைச் சிற்பிகளின் பெயர்ப் பொறிப்புகள்.', 'sources': ['South Indian Inscriptions Vol. I, Nos. 1-17', 'Epigraphia Indica Vol. X', 'Archaeological Survey of India Memoir No. 33'], 'content': '---\ntitle: "Mamallapuram Dharmaraja Ratha Royal Birudas & Master Sculptor Epigraphs"\nslug: "insc-mamallapuram-dharmaraja-ratha-biruda-epigraphs"\ncategory: "inscriptions"\ntype: "inscription"\nera: "Pallava Classical Era (c. 640–690 CE)"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "South Indian Inscriptions Vol. I, Nos. 1-17"\n  - "Epigraphia Indica Vol. X"\n  - "Archaeological Survey of India Memoir No. 33"\n---\n\n# Mamallapuram Dharmaraja Ratha Royal Birudas & Master Sculptor Epigraphs\n\n## 1. Epigraphic Corpus on the Monolithic Rathas\nThe Dharmaraja Ratha—the largest and most architecturally complex of the five monolithic temples at Mamallapuram—bears multiple labels incised in early Pallava Grantha characters:\n- Royal Birudas: *Sri Mamalla* ("The Great Wrestler"), *Atyantakama* ("He whose desires are limitless"), *Srinidhi* ("Abode of Wealth"), and *Nayanamanohara* ("Pleasing to the Eyes").\n- The dedicatory verses confirm that the monolithic rathas were conceived and excavated under King Narasimhavarman I Mamalla (r. 630–668 CE) following his historic victory over the Chalukyas at Badami.\n\n## 2. Inscriptional Mentions of Master Carvers\nCrucially, label epigraphs identify specific artisan lineages:\n- **Kevadha**: An archaic artisan title referring to the chief stone-cleaver and layout engineer who struck the reference plumb-lines across the raw granite outcrop.\n- Inscriptions praise the accuracy of the multi-tiered vimana (*kuta*, *sala*, and *panjara* miniature pavilions) carved top-down without the aid of scaffolding or mortar joints.\n', 'node_type': 'inscription', 'year_start': 600, 'year_end': 800}, {'category': 'inscriptions', 'slug': 'insc-saluvankuppam-atiranachanda-cave-temple-charters', 'file': 'insc-saluvankuppam-atiranachanda-cave-temple-charters.md', 'name_en': 'Saluvankuppam Atiranachanda Mandapa Cave Temple Dual-Script Charters', 'name_ta': 'சாளுவன்குப்பம் அதிரணசண்ட மண்டபக் குடைவரைக் கோயில் இருமொழிப் பட்டயங்கள்', 'era': 'Later Pallava Era (c. 700–728 CE)', 'thinai': 'Neithal', 'summary_en': 'Bilingual Grantha and Nagari rock inscriptions of Rajasimha Pallava on the Atiranachanda cave temple at Saluvankuppam recording rock-cut excavation techniques, Agamic temple consecration, and Somaskanda panel carvings.', 'summary_ta': 'சாளுவன்குப்பம் அதிரணசண்ட குடைவரைக் கோயிலில் காணப்படும் இராஜசிம்ம பல்லவனின் கிரந்த மற்றும் தேவநாகரி இருவகை வரிவடிவப் பாறைக் கல்வெட்டுகள்; பாறை குடைவு நுட்பங்கள் மற்றும் சோமாஸ்கந்தர் சிற்ப அர்ப்பணிப்புகள்.', 'sources': ['Epigraphia Indica Vol. X, No. 22', 'South Indian Inscriptions Vol. I, Nos. 21-22', 'ASI Architectural Survey of Temples No. 3'], 'content': '---\ntitle: "Saluvankuppam Atiranachanda Mandapa Cave Temple Dual-Script Charters"\nslug: "insc-saluvankuppam-atiranachanda-cave-temple-charters"\ncategory: "inscriptions"\ntype: "inscription"\nera: "Later Pallava Era (c. 700–728 CE)"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "Epigraphia Indica Vol. X, No. 22"\n  - "South Indian Inscriptions Vol. I, Nos. 21-22"\n  - "ASI Architectural Survey of Temples No. 3"\n---\n\n# Saluvankuppam Atiranachanda Mandapa Cave Temple Dual-Script Charters\n\n## 1. Dual-Script Epigraphic Architecture\nCarved into the rear and side walls of the rock-cut cave temple at Saluvankuppam (3 miles north of Mamallapuram), these identical Sanskrit verses are incised in two parallel scripts:\n1. Southern Pallava Grantha on the south wall.\n2. Northern Nagari on the north wall.\n\nThis deliberate epigraphic duality demonstrates that Mamallapuram was an imperial international center communicating its technical and political achievements to visitors from northern and southern India alike.\n\n## 2. Inscriptional Praise of Rock Engineering\nThe inscription eulogizes King Rajasimha (Atiranachanda):\n> *"Just as Ishvara resides forever on Mount Kailasa, may He dwell perpetually in this auspicious temple excavated from the core of the stone rock (*shilamaya-griham*)."*\n\nThe text commemorates the successful excavation of a deep pillared hall fronted by fluted columns resting upon the backs of couchant granite lions (*Simha-pada-thoon*).\n', 'node_type': 'inscription', 'year_start': 600, 'year_end': 800}, {'category': 'concepts', 'slug': 'concept-granite-monolith-scooping-and-quarry-wedge-splitting', 'file': 'concept-granite-monolith-scooping-and-quarry-wedge-splitting.md', 'name_en': 'Granite Monolith Top-Down Scooping, Wedge-Splitting & Chisel Pyrotechnics', 'name_ta': 'கருங்கல் ஒற்றைக்கல் மேல்-கீழ் குடைவு, ஆப்பு அடித்துப் பாறை பிளத்தல் மற்றும் உளித் தொழில் நுட்பம்', 'era': 'Pallava Classical Era', 'thinai': 'Neithal', 'summary_en': 'Engineering mechanics of free-standing granite monolith excavation: top-down terraced carving, dry wooden wedge expansion splitting, temper-hardened carbon steel chisels, and waste rock clearing.', 'summary_ta': 'சுயம்பு கருங்கற்பாறையை மேலிருந்து கீழாகப் படியமைத்துக் குடையும் பொறியியல்: உலர்ந்த மர ஆப்புகளுக்கு நீர் ஊற்றிப் பாறை பிளத்தல், பதப்படுத்தப்பட்ட எஃகு உளிகள் மற்றும் சிதைவுக்கல் அகற்றும் முறைகள்.', 'sources': ['ASI Technical Monograph on Mamallapuram', 'Srinivasan Cave-Temples of the Pallavas', 'Ancient Indian Quarrying Metallurgy'], 'content': '---\ntitle: "Granite Monolith Top-Down Scooping, Wedge-Splitting & Chisel Pyrotechnics"\nslug: "concept-granite-monolith-scooping-and-quarry-wedge-splitting"\ncategory: "concepts"\ntype: "concept"\nera: "Pallava Classical Era"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "ASI Technical Monograph on Mamallapuram"\n  - "Srinivasan Cave-Temples of the Pallavas"\n  - "Ancient Indian Quarrying Metallurgy"\n---\n\n# Granite Monolith Top-Down Scooping, Wedge-Splitting & Chisel Pyrotechnics\n\n## 1. Top-Down Monolithic Excavation Sequence\nUnlike structural stone buildings constructed by laying blocks from the foundation upward, Pallava monolithic shrines (*Rathas*) were carved exclusively from the finial (*stupi*) downward:\n1. **Boulder Profile Dressing**: A free-standing granite whaleback boulder was isolated by quarrying perimeter trenches.\n2. **Roof & Vimana Carving**: Master sculptors completed the finial, vaulted roof (*sala* or *kuta*), eaves, and gavaksha sun-windows first, eliminating the need for wooden scaffolding resting on lower tiers.\n3. **Pillar & Sanctum Extraction**: Sculptors worked downward to hollow out interior cells, leaving structural lion-pillars in place to bear the deadweight of the monolithic super-structure.\n\n## 2. Hydraulic Wooden Wedge Splitting (Aappu-Pilathal)\nTo cleave away tons of unwanted overburden without causing shock fractures to the central shrine:\n- Masons cut rectangular mortise pockets (2 inches wide, 4 inches deep) along natural granite grain fracture planes.\n- Dry seasoned wedges of hard wood (*acacia* or *tamarind*) were hammered firmly into the holes.\n- Boiling water was poured continuously over the wedges. The swelling fibers exerted radial hydrostatic pressure exceeding 2,000 psi, silently snapping the dense crystalline granite along the desired shear line.\n\n## 3. Chisel Metallurgy & Tempering\nExcavators employed high-carbon crucible steel (*wootz*) chisels:\n- Point chisels (*Koor-uli*) for rough spalling.\n- Flat chisels (*Vattu-uli*) for planar leveling.\n- Claw chisels for finishing textures. Masons kept portable charcoal hearths on-site to continuously re-forge and oil-temper blunted chisel edges.\n', 'node_type': 'concept', 'year_start': 600, 'year_end': 800}, {'category': 'concepts', 'slug': 'concept-talamana-iconometric-proportions-and-shilpa-sastra', 'file': 'concept-talamana-iconometric-proportions-and-shilpa-sastra.md', 'name_en': 'Talamana Iconometric Proportions, Plumb-Line Metrology & Shilpa-Sastra', 'name_ta': 'தாளமான உருவ அளவியல், தூக்குநூல் நுட்பம் மற்றும் சிற்ப சாஸ்திர விகிதங்கள்', 'era': 'Pallava to Chola Era', 'thinai': 'Neithal / Marutham', 'summary_en': 'Geometric and mathematical canons governing classical Tamil stone sculpture: Angula and Tala modular units, Dasa-tala deity ratios, plumb-line alignment grids (Sutra), and postural flexions (Bhanga).', 'summary_ta': 'பழங்காலத் தமிழ் சிற்பக் கலையின் கணித மற்றும் வடிவியல் நெறிகள்: அங்குலம், தாளம் அளவை அலகுகள், தசதாள விகிதங்கள், தூக்குநூல் கோடுகள் (சூத்திரம்) மற்றும் வளைவு நிலைகள் (பங்கம்).', 'sources': ['Mayamata Shilpa Shastra', 'Manasara Vastu Shastra Chap 55-66', 'Silappadikaram Commentary on Sculptural Proportion'], 'content': '---\ntitle: "Talamana Iconometric Proportions, Plumb-Line Metrology & Shilpa-Sastra"\nslug: "concept-talamana-iconometric-proportions-and-shilpa-sastra"\ncategory: "concepts"\ntype: "concept"\nera: "Pallava to Chola Era"\nthinai: "Neithal / Marutham"\nlanguage: "ta / en"\nsources:\n  - "Mayamata Shilpa Shastra"\n  - "Manasara Vastu Shastra Chap 55-66"\n  - "Silappadikaram Commentary on Sculptural Proportion"\n---\n\n# Talamana Iconometric Proportions, Plumb-Line Metrology & Shilpa-Sastra\n\n## 1. Modular Dimensioning Systems (Tala and Angula)\nClassical Tamil sculpture is grounded in the *Talamana* canon, where the unit of proportion is derived from the human body:\n- **Angula**: Standard finger-width (approx. 3/4 inch).\n- **Tala**: Length of the open palm from wrist crease to tip of the middle finger, exactly equal to the height of the sculpted face (12 Angulas).\n- **Dasa-Tala (10 Talas / 120 Angulas)**: The sovereign canon reserved for major deities (Siva, Vishnu) ensuring monumental stature and aesthetic majesty.\n- **Nava-Tala (9 Talas / 108 Angulas)**: Used for lesser devas, rishis, and noble kings.\n\n## 2. Plumb-Line Grid Rigging (Sutra-Dharana)\nBefore touching chisel to stone, master sculptors erected a wooden frame (*Phalaka*) over the block suspended with weighted plumb-lines:\n- **Brahma-Sutra**: The central vertical plumb-line passing through the crown, bridge of the nose, navel, and between the heels.\n- **Parsva-Sutra**: Flank lines defining maximum hip and shoulder deviations.\n- **Bhanga (Flexions)**: Modulating dynamic sculptural posture: *Sama-bhanga* (equipoised standing), *Abhanga* (subtle hip sway), and *Tri-bhanga* (dramatic triple curve seen in celestial maidens and dancers).\n', 'node_type': 'concept', 'year_start': 600, 'year_end': 800}, {'category': 'concepts', 'slug': 'concept-bas-relief-open-air-frieze-narrative-composition', 'file': 'concept-bas-relief-open-air-frieze-narrative-composition.md', 'name_en': 'Open-Air Bas-Relief Granite Friezes & Hydraulic Natural Cleft Integration', 'name_ta': 'திறந்தவெளிக் கருங்கல் புடைப்புச் சிற்பத் தொகுதிகள் மற்றும் இயற்கைப் பாறைப் பிளவு நீர்ம ஒருங்கமைப்பு', 'era': 'Pallava Classical Era (c. 650–700 CE)', 'thinai': 'Neithal', 'summary_en': "Artistic and hydraulic engineering of the 100-foot 'Descent of the Ganga' (Arjuna's Penance) open-air granite canvas: incorporating natural rock fissures into celestial river cascades, foreshortening perspective, and lifelike naturalism.", 'summary_ta': "மாமல்லபுரத்தின் 100 அடி நீள 'கங்காவதரணம்' திறந்தவெளிப் புடைப்புச் சிற்பப் பாறைப் பொறியியல்: இயற்கையான பாறைப் பிளவை தேவநதியாக மாற்றுதல், முப்பரிமாணக் காட்சிப் பார்வை மற்றும் இயல்பான விலங்குச் சிற்பங்கள்.", 'sources': ['Descent of the Ganga Relief Survey (ASI)', 'Sivaramamurti Mahabalipuram', 'Rajan Pallava Art and Architecture'], 'content': '---\ntitle: "Open-Air Bas-Relief Granite Friezes & Hydraulic Natural Cleft Integration"\nslug: "concept-bas-relief-open-air-frieze-narrative-composition"\ncategory: "concepts"\ntype: "concept"\nera: "Pallava Classical Era (c. 650–700 CE)"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "Descent of the Ganga Relief Survey (ASI)"\n  - "Sivaramamurti Mahabalipuram"\n  - "Rajan Pallava Art and Architecture"\n---\n\n# Open-Air Bas-Relief Granite Friezes & Hydraulic Natural Cleft Integration\n\n## 1. The Monolithic Granite Canvas\nMeasuring 96 feet in length and 43 feet in height, the colossal bas-relief known alternatively as *Arjuna\'s Penance* or *Bhagiratha\'s Tapas / Descent of the Ganga* is the largest open-air sculpted cliff face in the world:\n- The Pallava sculptors took advantage of two giant whaleback granite boulders separated by a deep natural vertical fracture.\n- Over 150 life-sized figures—gods, gandharvas, rishis, hunters, elephants, lions, deer, and swimming nagas—converge toward the central fissure.\n\n## 2. Integrated Hydraulic Cascade Mechanics\nArchaeological examination atop the rock ridge revealed an artificial plastered masonry cistern fed by seasonal rainwater collectors:\n- During festivals and state celebrations, sluices atop the cliff were opened.\n- Water cascaded down the central cleft, simulating the physical descent of the river Ganga from the heavens, flowing directly past sculpted multi-hooded Naga kings (*Nagaraja*) who appear to rise dynamically through real rushing water.\n\n## 3. Kinetic Naturalism & Animal Anatomic Fidelity\nPallava artisans broke with rigid hieratic conventions, rendering animal anatomy with astonishing sensitivity:\n- A herd of full-scale Asian elephants, led by a majestic tusker shielding infant calves sheltering beneath his belly.\n- A cat performing ascetic penance on one foot while playful mice scamper unmolested around its paws.\n', 'node_type': 'concept', 'year_start': 600, 'year_end': 800}, {'category': 'concepts', 'slug': 'concept-sthapati-guild-organization-and-sculptor-titles', 'file': 'concept-sthapati-guild-organization-and-sculptor-titles.md', 'name_en': 'Sthapati Guild Hierarchies, Royal Mason Titles & Ritual Tool Consecration', 'name_ta': 'சிற்பக் கலைஞர் வணிகக் குழுக்கள், அரச கட்டடக் கலைஞர் பட்டங்கள் மற்றும் ஆயுத பூஜை சடங்குகள்', 'era': 'Pallava to Imperial Chola Era', 'thinai': 'Marutham / Neithal', 'summary_en': 'Corporate division of labor within ancient Tamil architectural guilds: the master architect (Sthapati), chief designer (Sutragrahin), sculptor (Takshaka), and mason (Vardhaki), accompanied by royal honors and Ayudha puja rituals.', 'summary_ta': 'பழங்காலத் தமிழ்ச் சிற்பக் குழுக்களின் நால்வகை தொழில் பிரிவுகள்: முதன்மைத் தலைமைச் சிற்பி (ஸ்தபதி), தூக்குநூல் வரைவாளர் (சூத்ரகிராஹி), கல் சிற்பி (தட்சகன்) மற்றும் கட்டட மேஸ்திரி (வர்த்தகி) மற்றும் அரச விருதுகள்.', 'sources': ['Manasara Vastu Shastra Chap 2', 'South Indian Inscriptions Vol. II', 'Tolkappiyam Marapiyal'], 'content': '---\ntitle: "Sthapati Guild Hierarchies, Royal Mason Titles & Ritual Tool Consecration"\nslug: "concept-sthapati-guild-organization-and-sculptor-titles"\ncategory: "concepts"\ntype: "concept"\nera: "Pallava to Imperial Chola Era"\nthinai: "Marutham / Neithal"\nlanguage: "ta / en"\nsources:\n  - "Manasara Vastu Shastra Chap 2"\n  - "South Indian Inscriptions Vol. II"\n  - "Tolkappiyam Marapiyal"\n---\n\n# Sthapati Guild Hierarchies, Royal Mason Titles & Ritual Tool Consecration\n\n## 1. The Fourfold Technical Guild Hierarchy\nVastu and Shilpa manuals codified a strict four-tiered corporate division of responsibilities on imperial monument sites:\n1. **Sthapati (Chief Architect-Master)**: Well-versed in mathematics, astronomy, Sanskrit/Tamil Agamas, and overall structural design.\n2. **Sutragrahin (Layout Surveyor & Plumb-Master)**: The disciple or eldest son of the Sthapati, responsible for establishing foundation baselines, verticality, and plumb-lines (*Sutra*).\n3. **Takshaka (Master Stone Sculptor)**: Expert in chisel-work, rough blocking, iconographic detail, and portraiture.\n4. **Vardhaki (Joiner & Polish Mason)**: Master of final polishing, fine mortar dressing, and decorative scrollwork.\n\n## 2. Royal Honors & Inscriptional Titles\nKings conferred aristocratic privileges upon preeminent builders:\n- **Perun-thatchan ("Great Mason")**: Highest civil title awarded to temple builders.\n- **Tribhuvanacharya ("Master Architect of the Three Worlds")**: Royal designation bestowed upon architects of imperial vimanas like Thanjavur and Gangaikondacholapuram.\n- **Rathakara Assembly Rights**: Independent corporate councils holding legal autonomy to settle internal trade disputes, land transfers, and tax immunities.\n', 'node_type': 'concept', 'year_start': 600, 'year_end': 800}, {'category': 'characters', 'slug': 'char-mamallapuram-chief-sculptor-perun-thatchan', 'file': 'char-mamallapuram-chief-sculptor-perun-thatchan.md', 'name_en': 'Chief Royal Sculptor of the Mamallapuram Rathas (Perun-Thatchan)', 'name_ta': 'மாமல்லபுரம் ஒற்றைக்கல் இரதங்களின் தலைமை அரச சிற்பி (பெருந்தச்சன்)', 'era': 'Pallava Classical Era (c. 650 CE)', 'thinai': 'Neithal', 'summary_en': 'Master architect and court sthapati who executed the architectural vision of Narasimhavarman I Mamalla, translating five distinct timber shrine styles into monolithic granite.', 'summary_ta': 'நரசிம்மவர்ம மாமல்லனின் பேரரசு சிற்பக் கனவை நனவாக்கிய தலைமை அரச ஸ்தபதி; மரக் கட்டட பாணிகளை அழியாத ஒற்றைக்கல் கருங்கல் இரதங்களாக வடித்த வித்தகர்.', 'sources': ['Dharmaraja Ratha Grantha Inscriptions', 'ASI Epigraphical Memoirs'], 'content': '---\ntitle: "Chief Royal Sculptor of the Mamallapuram Rathas (Perun-Thatchan)"\nslug: "char-mamallapuram-chief-sculptor-perun-thatchan"\ncategory: "characters"\ntype: "character"\nera: "Pallava Classical Era (c. 650 CE)"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "Dharmaraja Ratha Grantha Inscriptions"\n  - "ASI Epigraphical Memoirs"\n---\n\n# Chief Royal Sculptor of the Mamallapuram Rathas (Perun-Thatchan)\n\n## 1. Visionary Translation of Living Architecture\nThe *Perun-Thatchan* of Mamallapuram faced an unprecedented structural challenge: carving complete shrines from the living bedrock without assembling precut masonry blocks. He orchestrated hundreds of apprentice carvers across the sandy dune ridge:\n- For the **Draupadi Ratha**, he replicated a thatched village hut with curving bamboo rafters and corner floral metal brackets carved in solid granite.\n- For the **Bhima Ratha**, he engineered an oblong wagon-vaulted roof (*sala*) with delicate horseshoe dormers (*kudu*).\n- For the **Dharmaraja Ratha**, he sculpted three ascending square tiers crowned by an octagonal dome (*griva* and *shikhara*).\n\n## 2. Technical Mastery of Stone Faults\nHe read the hidden fractures and quartz dikes inside the granite outcrop, strategically aligning sanctum doorways and structural lion columns to avoid geological faults, ensuring these monolithic wonders stood unharmed by maritime cyclonic gales for fourteen centuries.\n', 'node_type': 'character', 'year_start': 600, 'year_end': 800}, {'category': 'characters', 'slug': 'char-saluvankuppam-rock-cut-cave-carver', 'file': 'char-saluvankuppam-rock-cut-cave-carver.md', 'name_en': 'Master Rock-Cut Cave Carver & Yali Monolith Sculptor (Silpa-Kavalan)', 'name_ta': 'சாளுவன்குப்பம் குடைவரைக் குகை மற்றும் யாளி மண்டப தலைமைச் சிற்பி (சிற்பக் காவலன்)', 'era': 'Later Pallava Era (c. 710 CE)', 'thinai': 'Neithal', 'summary_en': 'Artisanal pioneer of the coastal rock shrine movement under Rajasimha Pallava, renowned for sculpting the iconic Tiger Cave lion mandapa and high-relief Somaskanda panels.', 'summary_ta': "இராஜசிம்ம பல்லவர் காலக் கடற்கரைப் பாறைச் சிற்ப முன்னோடி; புகழ்பெற்ற 'புலிக்குகை' யாளி முக மண்டபம் மற்றும் சோமாஸ்கந்தர் புடைப்புச் சிற்பங்களை வடித்த தலைமைச் சிற்பி.", 'sources': ['Saluvankuppam Excavations', 'Epigraphia Indica Vol. X'], 'content': '---\ntitle: "Master Rock-Cut Cave Carver & Yali Monolith Sculptor (Silpa-Kavalan)"\nslug: "char-saluvankuppam-rock-cut-cave-carver"\ncategory: "characters"\ntype: "character"\nera: "Later Pallava Era (c. 710 CE)"\nthinai: "Neithal"\nlanguage: "ta / en"\nsources:\n  - "Saluvankuppam Excavations"\n  - "Epigraphia Indica Vol. X"\n---\n\n# Master Rock-Cut Cave Carver & Yali Monolith Sculptor (Silpa-Kavalan)\n\n## 1. Sculpting the Yali Pavilion (Tiger Cave)\nOperating on the beachfront rocks of Saluvankuppam, this master artisan transformed an isolated coastal boulder into a theatrical open-air pavilion. Framing the central cella, he sculpted an archway of eleven roaring mythical lion-beasts (*vyalas* / *yalis*), creating an acoustic amphitheater used for royal music and dance performances.\n\n## 2. Somaskanda Panel Composition\nInside the Atiranachanda cave sanctuary, he perfected the classic Pallava *Somaskanda* motif: Siva and Uma seated side-by-side with infant Skanda (Murugan) between them, flanked by Brahma and Vishnu in the background. His chisel created delicate facial expressions, diaphanous drapery, and relaxed anatomical postures that defined South Indian rock art.\n', 'node_type': 'character', 'year_start': 600, 'year_end': 800}, {'category': 'places', 'slug': 'place-saluvankuppam-tiger-cave-and-monolith-sanctuary', 'file': 'place-saluvankuppam-tiger-cave-and-monolith-sanctuary.md', 'name_en': 'Saluvankuppam Tiger Cave & Monolithic Rock-Cut Sanctuary', 'name_ta': 'சாளுவன்குப்பம் புலிக்குகை மற்றும் ஒற்றைக்கல் குடைவரைச் சரணாலயம்', 'era': 'Pallava Era (c. 650–730 CE)', 'thinai': 'Neithal', 'summary_en': 'Seaside granitic archaeological complex north of Mamallapuram featuring the famous Yali Mandapa (Tiger Cave), Atiranachanda cave temple, and submerged tsunami-exposed brick foundations.', 'summary_ta': 'மாமல்லபுரத்திற்கு வடக்கே கடற்கரையில் அமைந்துள்ள வரலாற்றுச் சிறப்புமிக்க கருங்கல் சிற்ப வளாகம்; புகழ்பெற்ற யாளி மண்டபம், அதிரணசண்ட குடைவரை மற்றும் ஆழிப்பேரலையில் வெளிப்பட்ட சங்க கால செங்கல் கோயில் தளம்.', 'sources': ['Archaeological Survey of India Reports', 'Epigraphia Indica Vol. X', 'Subramanian Pallava Heritage of Saluvankuppam'], 'content': '---\ntitle: "Saluvankuppam Tiger Cave & Monolithic Rock-Cut Sanctuary"\nslug: "place-saluvankuppam-tiger-cave-and-monolith-sanctuary"\ncategory: "places"\ntype: "place"\nera: "Pallava Era (c. 650–730 CE)"\nthinai: "Neithal"\nlanguage: "ta / en"\ncoordinates: [12.6508, 80.1986]\nsources:\n  - "Archaeological Survey of India Reports"\n  - "Epigraphia Indica Vol. X"\n  - "Subramanian Pallava Heritage of Saluvankuppam"\n---\n\n# Saluvankuppam Tiger Cave & Monolithic Rock-Cut Sanctuary\n\n## 1. Coastal Geography & Geological Setting\nSaluvankuppam is situated 5 kilometers north of Mamallapuram along the sandy Coromandel surf. The site comprises massive granitic gneiss boulders protruding directly from the coastal dune sand, naturally sheltered by casuarina groves and maritime scrub.\n\n## 2. Archaeological Discoveries & Submerged Antiquity\nFollowing the 2004 Indian Ocean tsunami, archaeological explorations at Saluvankuppam uncovered the foundations of a buried Sangam-era brick temple dedicated to Murugan dating back to the 3rd century BCE, directly beneath the Pallava stone structures. This proves that the Pallava granite carvers were deliberately sanctifying an ancient sacred spot that had served as a coastal maritime pilgrimage center for over a thousand years.\n', 'node_type': 'place', 'year_start': 600, 'year_end': 800}, {'category': 'texts', 'slug': 'text-purananuru-adigaman-sugarcane-origin-poetry', 'file': 'text-purananuru-adigaman-sugarcane-origin-poetry.md', 'name_en': 'Purananuru Adigaman Sugarcane Introduction & Sangam Mill Hymns', 'name_ta': 'புறநானூறு அதியமான் கரும்பு அறிமுகம் மற்றும் சங்க கால ஆலை ஆவணப் பாடல்கள்', 'era': 'Sangam Classical Era (c. 300 BCE – 200 CE)', 'thinai': 'Mullai / Marutham', 'summary_en': 'Canonical Sangam poetry in Purananuru (v. 99, 392) by poetess Avvaiyar celebrating King Adigaman Neduman Anji’s ancestors introducing sugarcane into Tamilakam, alongside Perumpanarruppadai descriptions of night-running crushing mills.', 'summary_ta': 'புறநானூற்றில் ஔவையார் பாடிய பாடல்கள் (99, 392): அதியமான் நெடுமான் அஞ்சியின் முன்னோர்கள் கரும்பை வானுலகிலிருந்து/கடல் கடந்து கொண்டுவந்து பயிரிட்ட வரலாறு மற்றும் பெரும்பாணாற்றுப்படை காட்டும் இரவிலும் இயங்கும் கரும்பு ஆலைகள்.', 'sources': ['Purananuru 99, 392', 'Perumpanarruppadai lines 260-265', 'Pattinappalai 10-15', 'Ainkurunuru 65'], 'content': '---\ntitle: "Purananuru Adigaman Sugarcane Introduction & Sangam Mill Hymns"\nslug: "text-purananuru-adigaman-sugarcane-origin-poetry"\ncategory: "texts"\ntype: "text"\nera: "Sangam Classical Era (c. 300 BCE – 200 CE)"\nthinai: "Mullai / Marutham"\nlanguage: "ta / en"\nsources:\n  - "Purananuru 99, 392"\n  - "Perumpanarruppadai lines 260-265"\n  - "Pattinappalai 10-15"\n  - "Ainkurunuru 65"\n---\n\n# Purananuru Adigaman Sugarcane Introduction & Sangam Mill Hymns\n\n## 1. The Mythic-Historical Introduction of Sugarcane (Karumbu)\nIn *Purananuru* (v. 99), the celebrated poetess Avvaiyar addresses her patron King Adigaman Neduman Anji of Tagadur (modern Dharmapuri):\n> *"Amarar penu vanam nintu... arun-tiral karumbu thandhu..."* — "Your illustrious ancestors, through mighty valor, brought from the divine heavenly realms the rare sweet sugarcane stalk, planting it upon the fertile river soils of Tamil earth for all mortals to enjoy."\n\nThis literary remembrance points to an early historic introduction of elite domestic varieties of *Saccharum officinarum* into the Kongu upland river basins via trans-oceanic maritime routes.\n\n## 2. Sangam Descriptions of Crushing Mills (Aalai)\nIn *Perumpanarruppadai* (lines 260–265), the nocturnal operation of village sugarcane mills is captured with mechanical acoustic detail:\n- The groaning roar of rotating timber rollers crushing thick purple cane stalks was so thunderous that sleeping wild boars fled from surrounding bamboo fences.\n- Crushed fibrous bagasse (*salu*) was stacked into fuel heaps to feed open-pan boiling hearths that glowed like molten gold throughout the night.\n- The fragrant aroma of boiling raw juice (*saaru*) mixed with crushed cardamom and ginger perfumed agricultural settlements for leagues around.\n', 'node_type': 'text', 'year_start': -300, 'year_end': 300}, {'category': 'inscriptions', 'slug': 'insc-thiruvannamalai-sugar-mill-and-jaggery-tithes', 'file': 'insc-thiruvannamalai-sugar-mill-and-jaggery-tithes.md', 'name_en': 'Thiruvannamalai & South Arcot Sugarcane Mill Tithes & Molasses Charters', 'name_ta': 'திருவண்ணாமலை மற்றும் தென்னாற்காடு கரும்பு ஆலை வரி மற்றும் பாகு மானியப் பட்டயங்கள்', 'era': 'Medieval Chola & Hoysala Era (c. 1150–1280 CE)', 'thinai': 'Marutham', 'summary_en': 'Epigraphs from Thiruvannamalai and Pennar river temples recording royal taxes levied on sugarcane crushing mills (Karumbu-aalai-kaanam), jaggery tithes for temple sweet offerings, and canal irrigation weirs.', 'summary_ta': 'திருவண்ணாமலை மற்றும் பெண்ணையாற்றுப்படுகைக் கோயில் கல்வெட்டுகளில் காணப்படும் கரும்பு ஆலை வரிகள் (கரும்பு ஆலைக் காணம்), நைவேத்திய சர்க்கரை மானியங்கள் மற்றும் பாசனக் கால்வாய் உரிமைகள்.', 'sources': ['South Indian Inscriptions Vol. VIII, Nos. 65, 89', 'Thiruvannamalai Epigraphical Survey', 'Epigraphia Indica Vol. XXVII'], 'content': '---\ntitle: "Thiruvannamalai & South Arcot Sugarcane Mill Tithes & Molasses Charters"\nslug: "insc-thiruvannamalai-sugar-mill-and-jaggery-tithes"\ncategory: "inscriptions"\ntype: "inscription"\nera: "Medieval Chola & Hoysala Era (c. 1150–1280 CE)"\nthinai: "Marutham"\nlanguage: "ta / en"\nsources:\n  - "South Indian Inscriptions Vol. VIII, Nos. 65, 89"\n  - "Thiruvannamalai Epigraphical Survey"\n  - "Epigraphia Indica Vol. XXVII"\n---\n\n# Thiruvannamalai & South Arcot Sugarcane Mill Tithes & Molasses Charters\n\n## 1. Epigraphic Taxes on Crushing Installations\nTemple inscriptions from the Pennar river basin record specific agrarian taxes levied on mechanical processing equipment:\n- **Aalai-Kaanam**: An annual cash cess assessed on each operational sugarcane mill.\n- **Aalai-Vari**: Physical delivery of ten *tulams* of hard unrefined jaggery (*vellam*) and five pots of concentrated sugarcane molasses (*paagu*) per mill to support daily temple sweet offerings (*appam*, *pongal*, and *amirtu*).\n\n## 2. Inscriptional Water Sharing for Cane Wetlands\nBecause sugarcane requires continuous twelve-month wetland flooding, inscriptions record precise sluice allocations (*karumbu-nir-paaichal*):\n- Farmers cultivating sugarcane (*karumbadi*) were granted prioritized water rights from reservoir weirs during dry summer months (Chithirai and Vaikasi).\n- Epigraphs strictly forbade breaching canal bunds to prevent unauthorized flooding of adjacent dry grain fields.\n', 'node_type': 'inscription', 'year_start': 985, 'year_end': 1280}, {'category': 'inscriptions', 'slug': 'insc-tagadur-adigaman-sugarcane-endowment-charters', 'file': 'insc-tagadur-adigaman-sugarcane-endowment-charters.md', 'name_en': 'Tagadur Adigaman Royal Sugarcane Cultivation & Irrigation Weir Charters', 'name_ta': 'தகடூர் அதியமான் அரச கரும்புப் பண்ணை மற்றும் பாசன மதகுப் பட்டயங்கள்', 'era': 'Early Historic to Chola Era', 'thinai': 'Mullai / Marutham', 'summary_en': 'Inscriptional rock records and memorial hero stones from the Dharmapuri-Tagadur basin commemorating Adigaman royal canal engineering, millwright guilds, and expansive sugarcane estates.', 'summary_ta': 'தருமபுரி-தகடூர்ப் பாறைப் பொறிப்புகள் மற்றும் நடுகற்களில் பதிவான அதியமான் மன்னர்களின் கால்வாய்ப் பாசனப் பொறியியல், ஆலைத் தச்சர்கள் மற்றும் பெருங்கரும்புப் பண்ணை ஆவணங்கள்.', 'sources': ['Dharmapuri Inscriptions (State Dept of Archaeology 1975)', 'Epigraphia Indica Vol. XXX', 'Kongu Hero Stone Epigraphs'], 'content': '---\ntitle: "Tagadur Adigaman Royal Sugarcane Cultivation & Irrigation Weir Charters"\nslug: "insc-tagadur-adigaman-sugarcane-endowment-charters"\ncategory: "inscriptions"\ntype: "inscription"\nera: "Early Historic to Chola Era"\nthinai: "Mullai / Marutham"\nlanguage: "ta / en"\nsources:\n  - "Dharmapuri Inscriptions (State Dept of Archaeology 1975)"\n  - "Epigraphia Indica Vol. XXX"\n  - "Kongu Hero Stone Epigraphs"\n---\n\n# Tagadur Adigaman Royal Sugarcane Cultivation & Irrigation Weir Charters\n\n## 1. The Heritage of Tagadur Sugarcane\nThe fertile alluvial basin of the Sanatkumara and Ponnaiyar rivers surrounding Tagadur (Dharmapuri) was renowned across ancient South India as the cradle of Tamil sugarcane agriculture. Rock inscriptions and hero stone records (*Nadukal*) document royal land charters (*Kani*) reserved for royal sugarcane groves (*Adigaman-Karumbadi*).\n\n## 2. Agricultural Engineering & Stone Anicuts\nInscriptions record the construction of stone diversion dams (*kal-anai*) across rocky rapids, feeding perennial distribution channels:\n- Specialized field embankments protected soft juicy cane stalks from wild elephants and herds of wild boar.\n- Inscriptions praise millwrights (*Aalai-Kollan*) who cast iron pivot spindles and forged curved iron cane scrapers to prepare seed sets (*karumbu-karai*) for propagation.\n', 'node_type': 'inscription', 'year_start': -300, 'year_end': 1000}, {'category': 'concepts', 'slug': 'concept-hydraulic-and-oxen-driven-roller-sugarcane-crushing-mills', 'file': 'concept-hydraulic-and-oxen-driven-roller-sugarcane-crushing-mills.md', 'name_en': 'Hydraulic & Oxen-Driven Roller Sugarcane Crushing Mills (Karumbu-Aalai)', 'name_ta': 'நீரியல் மற்றும் எருது சுழற்றும் இரட்டை உருளைக் கரும்பு ஆலை இயந்திரவியல் (கரும்பு ஆலை)', 'era': 'Sangam to Medieval Era', 'thinai': 'Marutham', 'summary_en': 'Mechanical engineering of traditional Tamil sugarcane crushing apparatus: vertical and horizontal interlocking wooden gear rollers, rotary oxen sweeps, stone mortar expellers, and juice filtration troughs.', 'summary_ta': 'பாரம்பரியத் தமிழ்க் கரும்பு ஆலைகளின் இயந்திரவியல் வடிவமைப்பு: செங்குத்து மற்றும் கிடைமட்ட மரப் பற்கள் கொண்ட உருளைகள், எருது இழுக்கும் சுழல் நெம்புகோல் மற்றும் சாறு வடிகட்டும் தொட்டிகள்.', 'sources': ['Perumpanarruppadai lines 260-265', 'Tirumurai Inscriptional References', 'Tamil Agricultural Tool Ethnography'], 'content': '---\ntitle: "Hydraulic & Oxen-Driven Roller Sugarcane Crushing Mills (Karumbu-Aalai)"\nslug: "concept-hydraulic-and-oxen-driven-roller-sugarcane-crushing-mills"\ncategory: "concepts"\ntype: "concept"\nera: "Sangam to Medieval Era"\nthinai: "Marutham"\nlanguage: "ta / en"\nsources:\n  - "Perumpanarruppadai lines 260-265"\n  - "Tirumurai Inscriptional References"\n  - "Tamil Agricultural Tool Ethnography"\n---\n\n# Hydraulic & Oxen-Driven Roller Sugarcane Crushing Mills (Karumbu-Aalai)\n\n## 1. Mechanical Architecture of the Dual-Roller Press\nThe ancient Tamil *Karumbu-Aalai* was a marvel of pre-modern timber and iron mechanics:\n- **Interlocking Rollers (Urulai)**: Two vertical cylinders fashioned from dense seasoned timber (*Acacia nilotica* or *Diospyros ebenum*) carved with matching helical gear teeth along their tops.\n- **Drive Sweep (Marapu-Thadi)**: A 15-foot horizontal lever arm anchored to the master roller, harnessed to a pair of heavy draught bullocks walking in a continuous 30-foot circle.\n- **Feeder Gap**: Laborers fed stripped cane stalks into the counter-rotating pinch zone, crushing fibrous vascular bundles and expressing up to 60% of the cane\'s wet juice in a single pass.\n\n## 2. Waste Fiber Extraction & Collection Sump\n- **Bagasse Drainage**: Crushed dry stalks (*salu*) emerged on the far side, immediately tied into bundles for air-drying as furnace fuel.\n- **Stone Sump (Saaru-Kuzhi)**: Raw green juice flowed down a sloping stone channel lined with fine woven muslin cloth (*thuni*) to strain out coarse rind shreds, collecting in deep terracotta storage jars buried in the soil to keep the juice cool and prevent premature fermentation.\n', 'node_type': 'concept', 'year_start': -300, 'year_end': 300}, {'category': 'concepts', 'slug': 'concept-open-pan-sugar-boiling-clarification-and-jaggery-crystallization', 'file': 'concept-open-pan-sugar-boiling-clarification-and-jaggery-crystallization.md', 'name_en': 'Open-Pan Sugar Boiling Furnaces, Plant Clarification & Solid Jaggery Crystallization', 'name_ta': 'திறந்த கொப்பரை காய்ச்சும் உலைகள், தாவரச் சாறு தூய்மையாக்கம் மற்றும் அச்சு வெல்லப் படிகமாக்கல்', 'era': 'Sangam to Medieval Era', 'thinai': 'Marutham', 'summary_en': 'Chemical pyrotechnics of jaggery manufacture: multichambered draft furnaces fired by dried bagasse, organic mucilage clarification (Hibiscus / lime), strike-point temperature testing, and cooling wooden crystallization troughs.', 'summary_ta': 'வெல்லம் காய்ச்சும் வேதியியல் மற்றும் வெப்பப் பொறியியல்: சக்கை எரிக்கும் பலகண் உலைகள், வெண்டை-சுண்ணாம்பு சாறு கொண்டு கசடு நீக்குதல், பாகுப் பத ஆய்வு மற்றும் மரப் படிகத் தொட்டிகள்.', 'sources': ['Purananuru 392', 'Pathinen Siddhargal Gunavagadam', 'Traditional Jaggery Manufacture Manuals'], 'content': '---\ntitle: "Open-Pan Sugar Boiling Furnaces, Plant Clarification & Solid Jaggery Crystallization"\nslug: "concept-open-pan-sugar-boiling-clarification-and-jaggery-crystallization"\ncategory: "concepts"\ntype: "concept"\nera: "Sangam to Medieval Era"\nthinai: "Marutham"\nlanguage: "ta / en"\nsources:\n  - "Purananuru 392"\n  - "Pathinen Siddhargal Gunavagadam"\n  - "Traditional Jaggery Manufacture Manuals"\n---\n\n# Open-Pan Sugar Boiling Furnaces, Plant Clarification & Solid Jaggery Crystallization\n\n## 1. Multiple-Pan Flue Furnaces (Aalai-Aduppu)\nAncient Tamil sugar artisans engineered efficient sunken flue furnaces built from refractory red clay and river silt:\n- Fired exclusively with dried crushed cane bagasse (*salu*), requiring zero external timber firewood.\n- Three stepped shallow copper pans (*Kopparai*) sat over a continuous subterranean flue draft. Raw cold juice entered the coolest tail pan for pre-heating, moved to the middle pan for scum skimming, and finished in the hottest direct-fire striking pan.\n\n## 2. Organic Clarification Chemistry\nRaw cane juice contains proteins, waxes, and coloring matter that cause souring if unremoved:\n- Artisans added crushed mucilage of *Hibiscus esculentus* (wild okra / *Vendaik-kaai*) combined with a light slurry of slaked shell lime (*Kalla-sunnambu*).\n- The alkaline mucilage coagulated non-sugar colloidal impurities, floating them to the surface as a thick dark scum (*kasadu*), which was skimmed off with perforated bronze ladles.\n\n## 3. Strike Point & Crystallization (Vellam Forming)\n- **Padham (Strike Test)**: The master boiler dropped a spoonful of concentrated golden syrup into cold water. When the syrup rolled between finger and thumb into a soft pliable ball that cracked with a dull sound, boiling was halted at approx. 118–120°C.\n- **Cooling & Aeration**: Molten syrup was ladled into shallow boat-shaped wooden cooling troughs (*Thoni-maram*) and vigorously worked with wooden paddles to introduce air nucleation centers.\n- **Molding**: As crystalline jaggery precipitated, the semi-solid paste was pressed into spherical balls (*Urundai-vellam*) or inverted coconut shell molds (*Achu-vellam*).\n', 'node_type': 'concept', 'year_start': -300, 'year_end': 300}, {'category': 'concepts', 'slug': 'concept-crystallized-sugar-candy-kalkandu-and-confectionery-arts', 'file': 'concept-crystallized-sugar-candy-kalkandu-and-confectionery-arts.md', 'name_en': 'Crystallized Sugar Candy (Kalkandu), Palm Sugar Arts & Siddha Confections', 'name_ta': 'படிகச் சர்க்கரைக் கற்கண்டு, பனை வெல்லக் கலை மற்றும் சித்த மருத்துவ இனிப்பு மருந்துகள்', 'era': 'Sangam to Chola Era', 'thinai': 'Marutham / Mullai', 'summary_en': 'Secondary confectionery technology in ancient Tamilakam: slow earthen vessel crystallizers yielding rock sugar candy (Kalkandu), palm jaggery (Karupatti) boiling, and medicated herbal confections (Lehyam).', 'summary_ta': 'பழங்காலத் தமிழ் இரண்டாம் நிலை இனிப்புத் தொழில்நுட்பம்: மண்பானைகளில் நூல் விட்டு கற்கண்டு படிகமாக்கல், பனை வெல்லம் (கருப்பட்டி) காய்ச்சுதல் மற்றும் மூலிகை லேகிய செய்முறைகள்.', 'sources': ['Agathiyar Vaidya Kaviyam', 'Silappadikaram Canto 6', 'Theraiyar Yamaga Venba'], 'content': '---\ntitle: "Crystallized Sugar Candy (Kalkandu), Palm Sugar Arts & Siddha Confections"\nslug: "concept-crystallized-sugar-candy-kalkandu-and-confectionery-arts"\ncategory: "concepts"\ntype: "concept"\nera: "Sangam to Chola Era"\nthinai: "Marutham / Mullai"\nlanguage: "ta / en"\nsources:\n  - "Agathiyar Vaidya Kaviyam"\n  - "Silappadikaram Canto 6"\n  - "Theraiyar Yamaga Venba"\n---\n\n# Crystallized Sugar Candy (Kalkandu), Palm Sugar Arts & Siddha Confections\n\n## 1. Rock Sugar Crystallization (Kalkandu Mechanics)\nTo produce large, translucent monoclinic crystals of sucrose (*Kalkandu*):\n- High-grade clarified cane syrup was concentrated to supersaturation and poured into unglazed earthen amphorae.\n- Fine cotton threads were suspended vertically through the liquid from the mouth of the vessel.\n- The pots were buried in dark subterranean cellars surrounded by insulating rice husks for three to four weeks. As the solution slowly cooled, massive hexagonal crystal clusters grew along the cotton threads.\n\n## 2. Siddha Confectionery & Preservative Matrix\nIn Siddha medicine, sugar was not merely a sweetener but an essential biochemical carrier (*Anupanam*) and organic preservative:\n- **Lehyams**: Herbal decoctions boiled down with equal weights of jaggery and clarified butter to suspend heat-sensitive botanicals without microbial spoilage.\n- **Sarkarai Confections**: Sesame-jaggery crunch bars (*Ellurundai*), popped-rice honey clusters (*Pori-vilangurundai*), and cardamom-spiced milk sweets prepared for temple festivals.\n', 'node_type': 'concept', 'year_start': -300, 'year_end': 300}, {'category': 'concepts', 'slug': 'concept-sugar-merchant-guilds-and-monsoon-syrup-transport', 'file': 'concept-sugar-merchant-guilds-and-monsoon-syrup-transport.md', 'name_en': 'Sugar Merchant Guilds, Lac-Sealed Syrup Amphorae & Riverine Distribution', 'name_ta': 'சர்க்கரை வணிகக் குழுக்கள், அரக்கு முத்திரையிட்ட பாகுக் குடங்கள் மற்றும் ஆற்றுவழிப் போக்குவரத்து', 'era': 'Early Historic to Medieval Chola Era', 'thinai': 'Marutham / Neithal', 'summary_en': 'Logistical packaging and inland water transport of liquid cane syrup and solid jaggery: resin-sealed terracotta jars, bamboo river rafts (Kattumaram), and Manigramam guild export charters.', 'summary_ta': 'கரும்புப் பாகு மற்றும் வெல்லக் கட்டிகளைப் பாதுகாப்பாகக் கடத்தும் பொதியிடல் நுட்பங்கள்: அரக்கு பூசிய மட்கலன்கள், காவிரி ஆற்றுத் தெப்பப் போக்குவரத்து மற்றும் மணிக்கிராம வணிகக் குழு ஏற்றுமதிகள்.', 'sources': ['South Indian Inscriptions Vol. II', 'Pattinappalai lines 180-195', 'Epigraphia Indica Vol. IV'], 'content': '---\ntitle: "Sugar Merchant Guilds, Lac-Sealed Syrup Amphorae & Riverine Distribution"\nslug: "concept-sugar-merchant-guilds-and-monsoon-syrup-transport"\ncategory: "concepts"\ntype: "concept"\nera: "Early Historic to Medieval Chola Era"\nthinai: "Marutham / Neithal"\nlanguage: "ta / en"\nsources:\n  - "South Indian Inscriptions Vol. II"\n  - "Pattinappalai lines 180-195"\n  - "Epigraphia Indica Vol. IV"\n---\n\n# Sugar Merchant Guilds, Lac-Sealed Syrup Amphorae & Riverine Distribution\n\n## 1. Ceramic Packaging of Liquid Molasses (Paagu-Kudam)\nLiquid cane molasses (*paagu*) ferment rapidly if exposed to ambient airborne yeasts. To transport syrup hundreds of miles down the Kaveri to coastal ports:\n- Earthen storage jars (*kudam*) were fired with internal black-burnished slips.\n- Filled jars were stoppered with clay disks wrapped in fine linen and sealed hermetically with boiled tree resin and red shellac (*arrakku*).\n- Jars were nested into woven straw cradles to absorb carriage shocks over rough cart roads.\n\n## 2. Riverine Flotillas along the Kaveri & Pennar\nDuring high monsoon water levels, sugar guilds loaded flat-bottomed timber rafts (*Theppam*) and basket coracles (*Parisal*) at interior river landings such as Karur and Dharmapuri:\n- Rafts floated downstream with the current to the coastal emporium of Poompuhar in under four days.\n- In coastal ports, foreign merchants (Yavanas, Arabs, and Chinese) purchased Tamil jaggery and refined candy as sea rations, utilizing sugar\'s high caloric density and scurvy-preventing mineral content.\n', 'node_type': 'concept', 'year_start': 985, 'year_end': 1280}, {'category': 'characters', 'slug': 'char-tagadur-master-sugarcane-millwright-aalai-kollan', 'file': 'char-tagadur-master-sugarcane-millwright-aalai-kollan.md', 'name_en': 'Master Sugarcane Millwright & Mechanical Axle Engineer (Aalai-Kollan)', 'name_ta': 'தகடூர் தலைமை கரும்பு ஆலை இயந்திரவியல் சிற்பி (ஆலைக் கொல்லன்)', 'era': 'Sangam Early Historic Era', 'thinai': 'Mullai / Marutham', 'summary_en': 'Preeminent mechanical carpenter and blacksmith of Tagadur, renowned for forging iron-journaled wooden roller gear assemblies and heavy timber oxen sweep arms.', 'summary_ta': 'தகடூரின் தலைசிறந்த இயந்திரவியல் தச்சன் மற்றும் கொல்லன்; இரும்பு அச்சு பொருத்தப்பட்ட மர உருளைப் பற்கள் மற்றும் எருது சுழற்றும் நெம்புகோல் இயந்திரங்களை வடித்த வித்தகர்.', 'sources': ['Purananuru 99 Commentary', 'Kongu Archaeological Tool Studies'], 'content': '---\ntitle: "Master Sugarcane Millwright & Mechanical Axle Engineer (Aalai-Kollan)"\nslug: "char-tagadur-master-sugarcane-millwright-aalai-kollan"\ncategory: "characters"\ntype: "character"\nera: "Sangam Early Historic Era"\nthinai: "Mullai / Marutham"\nlanguage: "ta / en"\nsources:\n  - "Purananuru 99 Commentary"\n  - "Kongu Archaeological Tool Studies"\n---\n\n# Master Sugarcane Millwright & Mechanical Axle Engineer (Aalai-Kollan)\n\n## 1. Lineage & Craft Specialization\nOperating in the artisan street (*Kammalar-theru*) of ancient Tagadur, the *Aalai-Kollan* combined mastery of heavy joinery carpentry with blacksmithing pyrotechnics. Royal charters endowed him with tax-free fields (*Thatcha-kaani*) to maintain all royal and communal cane mills throughout the harvest season.\n\n## 2. Mechanical Precision & Maintenance\n- He selected knot-free hearts of hardwood trees cured in swamp mud for two seasons to prevent splitting under tremendous crushing torque.\n- He forged square-headed wrought-iron journal pins driven into the axis of each wooden roller, seating them in greased stone bearings lubricated with castor oil (*Amanakku-ennai*), eliminating catastrophic friction fire during non-stop night operations.\n', 'node_type': 'character', 'year_start': -300, 'year_end': 300}, {'category': 'characters', 'slug': 'char-kaveri-basin-sugar-boiling-artisan-vellam-kaachuvor', 'file': 'char-kaveri-basin-sugar-boiling-artisan-vellam-kaachuvor.md', 'name_en': 'Master Sugar Boiler & Crystallization Technician (Vellam-Kaachuvor)', 'name_ta': 'காவிரிப் படுகை தலைமை வெல்லம் காய்ச்சும் வேதியியல் வித்தகர் (வெல்லம் காய்ச்சுவோர்)', 'era': 'Medieval Chola Era (c. 1100 CE)', 'thinai': 'Marutham', 'summary_en': 'Experienced pyrotechnic artisan supervising giant copper boiling vats, expert in observing bubble patterns, organic scum skimming, and cooling jaggery crystal nucleation.', 'summary_ta': 'பெரிய செப்புக் கொப்பரைகளில் வெல்லம் காய்ச்சும் மூத்த வேதியியல் வித்தகர்; கொதிக்கும் குமிழி வடிவங்கள் மூலம் பாகுப் பதம் அறிதல், கசடு நீக்குதல் மற்றும் படிகமாக்கல் கலைஞர்.', 'sources': ['South Indian Inscriptions Vol. VIII', 'Traditional Jaggery Artisans Guild Records'], 'content': '---\ntitle: "Master Sugar Boiler & Crystallization Technician (Vellam-Kaachuvor)"\nslug: "char-kaveri-basin-sugar-boiling-artisan-vellam-kaachuvor"\ncategory: "characters"\ntype: "character"\nera: "Medieval Chola Era (c. 1100 CE)"\nthinai: "Marutham"\nlanguage: "ta / en"\nsources:\n  - "South Indian Inscriptions Vol. VIII"\n  - "Traditional Jaggery Artisans Guild Records"\n---\n\n# Master Sugar Boiler & Crystallization Technician (Vellam-Kaachuvor)\n\n## 1. Empirical Pyrotechnic Mastery\nStanding beside the roaring bagasse furnace of a Kaveri delta estate, the *Vellam-Kaachuvor* possessed generational sensory intuition. He evaluated temperature and sucrose concentration purely through acoustic and visual signs:\n- As the juice boiled down, the bubbling sound changed from a watery hiss to a deep muffled thud (*murasu-satham*).\n- The foaming crest transformed from pale straw-white to deep amber gold, producing viscous strands that curled like fine spider silk when drawn from the paddle.\n\n## 2. Guild Certifications & Confection Standards\nHe regulated apprentice boilers across the delta, ensuring temple shipments contained zero burned carbon sediment. His certified stamped jaggery balls were prized throughout imperial Chola temple kitchens for sweet rice offerings (*Sarkarai-Pongal*).\n', 'node_type': 'character', 'year_start': 985, 'year_end': 1280}, {'category': 'places', 'slug': 'place-dharmapuri-adigaman-sugarcane-valley', 'file': 'place-dharmapuri-adigaman-sugarcane-valley.md', 'name_en': 'Dharmapuri Tagadur Adigaman Sugarcane Valley & Historic Mills', 'name_ta': 'தருமபுரி தகடூர் அதியமான் கரும்புப் பள்ளத்தாக்கு மற்றும் வரலாற்று ஆலைகள்', 'era': 'Sangam Classical Era (c. 300 BCE – 300 CE)', 'thinai': 'Mullai / Marutham', 'summary_en': 'Historic riverine basin of Tagadur in northwestern Tamil Nadu celebrated as the legendary cradle of Tamil sugarcane agriculture, featuring ancient canals, stone weirs, and mill sites.', 'summary_ta': 'வடமேற்குத் தமிழ்நாட்டின் வரலாற்றுச் சிறப்புமிக்க தகடூர்ப் படுகை; கரும்பு பயிரிடலைத் தொடங்கிவைத்த புகழ்பெற்ற ஆற்றுப் பள்ளத்தாக்கு, பழங்காலக் கால்வாய்கள் மற்றும் ஆலைத் தளங்கள்.', 'sources': ['Purananuru 99, 392', 'Dharmapuri Archaeological Gazetteer', 'State Archaeology Reports'], 'content': '---\ntitle: "Dharmapuri Tagadur Adigaman Sugarcane Valley & Historic Mills"\nslug: "place-dharmapuri-adigaman-sugarcane-valley"\ncategory: "places"\ntype: "place"\nera: "Sangam Classical Era (c. 300 BCE – 300 CE)"\nthinai: "Mullai / Marutham"\nlanguage: "ta / en"\ncoordinates: [12.1211, 78.1582]\nsources:\n  - "Purananuru 99, 392"\n  - "Dharmapuri Archaeological Gazetteer"\n  - "State Archaeology Reports"\n---\n\n# Dharmapuri Tagadur Adigaman Sugarcane Valley & Historic Mills\n\n## 1. Topography & River Confluences\nDharmapuri (ancient Tagadur) is situated in a broad, fertile undulating basin fed by the Sanatkumara river and seasonal tributaries descending from the Shevaroy and Melagiri hills. The rich ferruginous red loam mixed with alluvial deposits created an ideal soil chemistry for high-sugar content purple canes (*Saccharum officinarum*).\n\n## 2. Archaeological Stratigraphy of Sugar Manufacture\nArchaeological field surveys across the Dharmapuri valley uncovered ancient stone crushing mortars, channel sluices, and extensive ceramic wasters from large storage amphorae. Classical hero stone inscriptions in the surrounding hills depict local chieftains defending agricultural canal sluices against cattle and boundary raids.\n', 'node_type': 'place', 'year_start': -300, 'year_end': 300}]

